window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1cd0d7f5c2bba13f"]={"versions": [{"id": "FIG-1cd0d7f5c2bba13f", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation eines Datenstrukturtyps innerhalb der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library, Profil 6). Der Typ dient zur Abbildung des internen Zustands der Senderichtung (Protect-Zustand).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Definierte Struktur:</p>\n<ul class=\"fig-list\"><li>«structure» <code>E2E_P06Types::E2E_P06ProtectStateType</code>\n</li></ul>\n<p class=\"fig-p\">Attribute:</p>\n<ul class=\"fig-list\"><li><code>+ Counter :uint8</code>: Öffentliches Datenelement vom Typ <code>uint8</code> zur Verwaltung des fortlaufenden Sequenzzählers für Profil 6.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne Verhaltens- oder Sequenzdarstellung. Die Struktur wird instanziiert und im Kontext der Schutzfunktion <code>E2E_P06Protect</code> als Zustandsspeicher zwischen aufeinanderfolgenden Funktionsaufrufen aktualisiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Typdefinition für AUTOSAR Classic E2E Profile 6. Implementierungen der E2E-Bibliothek müssen die Struktur <code>E2E_P06ProtectStateType</code> mit dem Member <code>Counter</code> (<code>uint8</code>) bereitstellen. Der Zustand muss vom Aufrufer vor der Erstverwendung initialisiert und persistent über Sendezyklen gehalten werden.</p>"}, {"id": "FIG-309ab00a4c64f514", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation eines Datenstrukturtyps innerhalb der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library, Profil 6). Der Typ dient zur Abbildung des internen Zustands der Senderichtung (Protect-Zustand).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Definierte Struktur:</p>\n<ul class=\"fig-list\"><li>«structure» <code>E2E::E2E_P06Types::E2E_P06ProtectStateType</code>\n</li></ul>\n<p class=\"fig-p\">Attribute:</p>\n<ul class=\"fig-list\"><li><code>+ Counter :uint8</code>: Öffentliches Datenelement vom Typ <code>uint8</code> zur Verwaltung des fortlaufenden Sequenzzählers für Profil 6.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne Verhaltens- oder Sequenzdarstellung. Die Struktur wird instanziiert und im Kontext der Schutzfunktion <code>E2E_P06Protect</code> als Zustandsspeicher zwischen aufeinanderfolgenden Funktionsaufrufen aktualisiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Typdefinition für AUTOSAR Classic E2E Profile 6. Implementierungen der E2E-Bibliothek müssen die Struktur <code>E2E_P06ProtectStateType</code> mit dem Member <code>Counter</code> (<code>uint8</code>) bereitstellen. Der Zustand muss vom Aufrufer vor der Erstverwendung initialisiert und persistent über Sendezyklen gehalten werden.</p>"}, {"id": "FIG-5b3d2dfec3fcaa29", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation eines Datenstrukturtyps innerhalb der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library, Profil 6). Der Typ dient zur Abbildung des internen Zustands der Senderichtung (Protect-Zustand).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Definierte Struktur:</p>\n<ul class=\"fig-list\"><li>«structure» <code>E2E_P06Types::E2E_P06ProtectStateType</code>\n</li></ul>\n<p class=\"fig-p\">Attribute:</p>\n<ul class=\"fig-list\"><li><code>+ Counter: uint8</code>: Öffentliches Datenelement vom Typ <code>uint8</code> zur Verwaltung des fortlaufenden Sequenzzählers für Profil 6.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne Verhaltens- oder Sequenzdarstellung. Die Struktur wird instanziiert und im Kontext der Schutzfunktion <code>E2E_P06Protect</code> als Zustandsspeicher zwischen aufeinanderfolgenden Funktionsaufrufen aktualisiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Typdefinition für AUTOSAR Classic E2E Profile 6. Implementierungen der E2E-Bibliothek müssen die Struktur <code>E2E_P06ProtectStateType</code> mit dem Member <code>Counter</code> (<code>uint8</code>) bereitstellen. Der Zustand muss vom Aufrufer vor der Erstverwendung initialisiert und persistent über Sendezyklen gehalten werden.</p>"}], "trans": [{"from": "FIG-1cd0d7f5c2bba13f", "to": "FIG-309ab00a4c64f514", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Paketpfad im Typnamen: Dem Namensraum <code>E2E_P06Types::E2E_P06ProtectStateType</code> wird das übergeordnete Paket <code>E2E::</code> vorangestellt (<code>E2E::E2E_P06Types::E2E_P06ProtectStateType</code>).\n</li></ul>"}, {"from": "FIG-309ab00a4c64f514", "to": "FIG-5b3d2dfec3fcaa29", "fr": "R4.3.1", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Paketpfad im Typnamen: Das übergeordnete Präfix <code>E2E::</code> entfällt wieder; der Typname lautet <code>E2E_P06Types::E2E_P06ProtectStateType</code>.\n</li><li>Attributformatierung: Leerzeichen vor dem Doppelpunkt im Attribut <code>Counter :uint8</code> entfällt zu <code>Counter: uint8</code>.\n</li></ul>"}]};
